"""Zip-based targets: ``pyz`` (zipapp) and ``lambda`` (AWS Lambda deployment package)."""

from __future__ import annotations

import runpy
import stat
import zipfile
from typing import TYPE_CHECKING

from shakeout.emit import write_manifest
from shakeout.emit.tree import write_tree

if TYPE_CHECKING:
    from pathlib import Path

    from shakeout.emit import BuildResult
    from shakeout.result import ShakeResult

_EPOCH = (1980, 1, 1, 0, 0, 0)  # earliest zip timestamp: archives are reproducible

ZIPAPP_MAIN = """\
# Generated by shakeout: run the entry module of this archive as __main__.
def _shakeout_register_sources(loader, main_file, names, eager):
    # Make archived sources visible to linecache (tracebacks, warnings, inspect). CPython only
    # does this lazily for tracebacks and splits with str.splitlines (wrong for \\f, \\v...).
    import linecache
    import os

    archive = os.path.dirname(main_file)

    def read(name):
        return loader.get_data(os.path.join(archive, *name.split("/"))).decode("utf-8")

    for name in names:
        key = os.path.join(archive, *name.split("/"))
        if name in eager:
            text = read(name)
            lines = [line + "\\n" for line in text.split("\\n")]
            if lines and lines[-1] == "\\n":
                lines.pop()
            linecache.cache[key] = (len(text), None, lines, key)
        else:
            linecache.cache[key] = (lambda name=name: read(name),)


_shakeout_register_sources(__loader__, __file__, {names!r}, {eager!r})
del _shakeout_register_sources

import runpy

runpy.run_module({module!r}, run_name="__main__", alter_sys=True)
"""
_ODD_SEPARATORS = ("\f", "\v", "\x1c", "\x1d", "\x1e", "\x85", "\u2028", "\u2029")


class ArchiveError(ValueError):
    """The requested archive cannot be built for this entry point."""


def _zip_dir(
    src: Path, dest: Path, *, extra: dict[str, str] | None = None, prefix: bytes = b""
) -> None:
    files = sorted(p for p in src.rglob("*") if p.is_file())
    dest.parent.mkdir(parents=True, exist_ok=True)
    with dest.open("wb") as fh:
        fh.write(prefix)
        with zipfile.ZipFile(fh, "w", zipfile.ZIP_DEFLATED) as zf:
            for name, text in sorted((extra or {}).items()):
                zf.writestr(_info(name), text)
            for path in files:
                info = _info(path.relative_to(src).as_posix())
                if path.stat().st_mode & stat.S_IXUSR:
                    info.external_attr = 0o755 << 16
                zf.writestr(info, path.read_bytes())


def _info(name: str) -> zipfile.ZipInfo:
    info = zipfile.ZipInfo(name, date_time=_EPOCH)
    info.external_attr = 0o644 << 16
    info.compress_type = zipfile.ZIP_DEFLATED
    return info


def write_pyz(result: ShakeResult, out: Path) -> BuildResult:
    """Write ``out/<entry stem>.pyz``, runnable with ``python app.pyz``."""
    module = result.entry_module if result.options.library else result.entry.stem
    if result.options.library or not module.isidentifier():
        msg = (
            f"pyz needs a script entry whose name is a valid module name, not {result.entry.name!r}"
        )
        raise ArchiveError(msg)
    staging = out / ".pyz-staging"
    built = write_tree(result, staging, target="pyz")
    path = out / f"{result.entry.stem}.pyz"
    sources = sorted(p.relative_to(staging).as_posix() for p in staging.rglob("*.py"))
    eager = sorted(
        name
        for name in sources
        if any(sep in (staging / name).read_text(encoding="utf-8") for sep in _ODD_SEPARATORS)
    )
    main = ZIPAPP_MAIN.format(module=module, names=sources, eager=eager)
    _zip_dir(staging, path, extra={"__main__.py": main}, prefix=b"#!/usr/bin/env python3\n")
    path.chmod(0o755)
    built.run_path = path
    built.out = out
    built.runtime_files = [f"{path}/__main__.py", str(runpy.__file__), "<frozen runpy>"]
    return built


def write_lambda(result: ShakeResult, out: Path) -> BuildResult:
    """Write ``out/package/`` and ``out/<entry stem>.zip`` for AWS Lambda.

    The handler setting is ``<entry module>.<export>`` (also listed in the manifest).
    """
    if not result.options.library:
        msg = "the lambda target needs the handler name: set exports, e.g. exports = ['handler']"
        raise ArchiveError(msg)
    package = out / "package"
    built = write_tree(result, package, target="lambda")
    write_manifest(package / "shakeout-manifest.json", built.manifest)
    path = out / f"{result.entry.stem}.zip"
    _zip_dir(package, path)
    built.run_path = path
    built.out = out
    return built
